"use strict";exports.formatTime=t=>{if(!t)return"";const e=new Date(t),r=(new Date).getTime()-e.getTime(),o=Math.floor(r/6e4),a=Math.floor(r/36e5),g=Math.floor(r/864e5);return o<1?"刚刚":o<60?`${o}分钟前`:a<24?`${a}小时前`:g<30?`${g}天前`:`${e.getFullYear()}-${(e.getMonth()+1).toString().padStart(2,"0")}-${e.getDate().toString().padStart(2,"0")}`},exports.getBottleTypeName=t=>({1:"普通瓶",2:"语音瓶",3:"秘密瓶"}[t]||"普通瓶"),exports.getCategoryName=t=>({1:"日常",2:"深夜emo",3:"情感"}[t]||"日常");
